# Basic Drawing Constants
.eqv BASE_ADDRESS 0x10008000
.eqv SCREEN_WIDTH 64	# Display width / unit width
.eqv SCREEN_HEIGHT 64	# Diplay height / unit height
.eqv SLEEP 40
.eqv SLEEP_SLOW 100


# Colours
.eqv BACKGROUND_COLOUR 0X00B0E6F2
.eqv WHITE 0x00ffffff
.eqv BLACK 0x00000000
.eqv PINK 0x00EC008C
.eqv RED 0x00D30000
.eqv DARK_BLUE 0x001C57
.eqv PURPLE 0x00A782EC
.eqv DARK_PURPLE 0x008E68D6
