####################################


# Physics (- is up and + is down)
.eqv GRAV_ACCEL 1	# gravitational acceleration applied
.eqv FALL_SPEED 1		# pixels per frame can we fall at
.eqv JUMP_SPEED -6 	# pixels per frame can we jump up at

# PLAYER/HEARTS
.eqv PLAYER_WIDTH 3
.eqv PLAYER_HEIGHT 4


# Platform positions
.eqv PLAYER_START_X 30
.eqv PLAYER_START_Y 55
.eqv PLATFORM1_START_X 26
.eqv PLATFORM1_START_Y 60
.eqv PLATFORM2_START_X 12
.eqv PLATFORM2_START_Y 48
.eqv PLATFORM2B_START_X 48
.eqv PLATFORM2B_START_Y 54
