.eqv PLATFORM3_START_Y 36
.eqv PLATFORM4_START_X 26
.eqv PLATFORM4_START_Y 24
.eqv PLATFORM5_START_X 48
.eqv PLATFORM5_START_Y 12


# Pickups
.eqv PICKUP_SIZE 2
.eqv PICKUP1_X 12
.eqv PICKUP1_Y 28
.eqv PICKUP2_X 12
.eqv PICKUP2_Y 12
.eqv PICKUP_HEALTH_X 46
.eqv PICKUP_HEALTH_Y 28

.eqv SLOW_TIME 25 # number of frames with slowed time

.data

# Platforms
PLATFORM1: .word PLATFORM1_START_X, PLATFORM1_START_Y, 12
PLATFORM2: .word PLATFORM2_START_X, PLATFORM2_START_Y, 12
