# Heart positions
HEALTH: .word 3   # Player starts with 3 hearts
HEART1: .word 2, 2
HEART2: .word 8, 2
HEART3: .word 14, 2



.text
.globl main
main:

# s0 = game status (0 = play, 1 = win, 2 = lose)
# s1 = frog x position (bottom left)
# s2 = frog y position (bottom left)
# s3 = frog on platform
# s4 = vertical velocity
# s5 = slow time(positive number - 0)
# s6 = double jump (0- not active, 1- able to double jump, 2 - already double jumped)


# Initialize global variables
li $s0, 0
li $s1, PLAYER_START_X
li $s2, PLAYER_START_Y
li $s3, 0
li $s4, 0
li $s5, 0
li $s6, 0
li $s7, 0

GAME_LOOP:

	beq $s0, 1, PLAYER_WIN
	beq $s0, 2, PLAYER_LOSE
	
# ********************** GRAVITY *************************************
	
	GRAVITY:
		jal APPLY_GRAVITY
		j CHECK_INPUT
		
# ********************** GRAVITY *************************************
	
# ********************** KEY INPUT *************************************
	
	CHECK_INPUT: # Input Logic here
	li $t9, 0xffff0000
	lw $t8, 0($t9)
	bne $t8, 1, COLLISION_AND_MOVEMENT # No key pressed
	
	lw $t0, 4($t9) # t0 = key pressed
	
	beq $t0, KEY_W, W_PRESSED
	beq $t0, KEY_A, A_PRESSED
	beq $t0, KEY_S, S_PRESSED
	beq $t0, KEY_D, D_PRESSED
	beq $t0, KEY_R, R_PRESSED
	beq $t0, KEY_Q, Q_PRESSED
		
	j COLLISION_AND_MOVEMENT
		
	W_PRESSED:
		jal HANDLE_W
		j COLLISION_AND_MOVEMENT
	A_PRESSED:
		jal HANDLE_A
		j COLLISION_AND_MOVEMENT
	S_PRESSED:
		jal HANDLE_S
		j COLLISION_AND_MOVEMENT
	D_PRESSED:
		jal HANDLE_D
		j COLLISION_AND_MOVEMENT
	R_PRESSED:
		jal RESTART
		j GAME_SLEEP
	Q_PRESSED:
		jal QUIT_GAME
		
# ********************** KEY INPUT *************************************
	
# ********************** KEY HANDLERS *************************************

HANDLE_W:
	beq $s3, 0, NOT_ON_PLATFORM
	li $s4, JUMP_SPEED
	li $s3, 0
	jr $ra
	
	NOT_ON_PLATFORM:		
	
	beq $s6, 2, NO_DJ
	beq $s6, 0, NO_DJ
	addi $s4, $s4, -4
	
	blt $s4, JUMP_SPEED, ABOVE_FALL_SPEED
	j NOT_ABOVE_FALL_SPEED
	
	ABOVE_FALL_SPEED:
	li $s4, JUMP_SPEED
	
	NOT_ABOVE_FALL_SPEED:
	li $s3, 0
	

	li $s6, 2
	
	NO_DJ:
	jr $ra

HANDLE_A:
	addi $s1, $s1, -2
	jr $ra
	
HANDLE_S:
	addi $s2, $s2, 1
	jr $ra
	
HANDLE_D:
	addi $s1, $s1, 2
	jr $ra

# ********************** KEY HANDLERS *************************************
	
# ********************** COLLISION AND MOVEMENT *************************************
	
	COLLISION_AND_MOVEMENT:	
		jal CHECK_BOUNDS
		jal MOVE_OBJECTS
		jal CHECK_PLATFORMS
		jal CHECK_OBJECT_COLLISION
		jal UPDATE_PLAYER_VERT
		
		j DRAW
		
# ********************** COLLISION AND MOVEMENT *************************************
	
# ********************** DRAW EVERYTHING *************************************
	
	DRAW: # Draw Order
		jal CLEAR_SCREEN
		jal DRAW_PLATFORMS
		jal DRAW_PLAYER
		jal DRAW_PICKUPS
		jal DRAW_HEARTS
		j GAME_STATUS
		
# ********************** DRAW EVERYTHING *************************************
	
# ********************** GAME STATUS  *************************************
	
	GAME_STATUS:
		jal CHECK_GAME_STATUS
		j GAME_SLEEP
	
	PLAYER_WIN:
		la $a0, WIN_PATTERN
		jal DRAW_SCREEN
		jal DRAW_HEARTS
		j CHECK_INPUT_IN_SCREEN
		
	PLAYER_LOSE:
		la $a0, GAME_OVER_PATTERN
		jal DRAW_SCREEN
		#jal DRAW_HEARTS

		j CHECK_INPUT_IN_SCREEN
		
	CHECK_INPUT_IN_SCREEN:
		li $t9, 0xffff0000
		lw $t8, 0($t9)
		bne $t8, 1, GAME_SLEEP 		# No key pressed
		lw $t0, 4($t9) 			# t0 = key pressed
		
	CHECK_KEY_PRESSED:				
		beq $t0, KEY_R, RESTART_PRESSED
		beq $t0, KEY_Q, QUIT_GAME
		j GAME_SLEEP
		
	RESTART_PRESSED:
		jal RESTART
		j GAME_SLEEP
	
		
	QUIT_GAME:
		la $a0, QUIT_GAME_PATTERN
		jal DRAW_SCREEN
		j END
	
	GAME_SLEEP: # Sleep and restart the loop
	li $v0, 32
	bgtz $s5, GAME_SLEEP_SLOW
	li $a0, SLEEP
	syscall
	j END_SLEEP
	
	GAME_SLEEP_SLOW:
	li $a0, SLEEP_SLOW
	addi $s5, $s5, -1
	syscall
	
	END_SLEEP:
	
	j GAME_LOOP	
	
	# Terminate program gracefullly
	END:
	li $v0, 10
	syscall

# ********************** GAME STATUS  *************************************

# ----------------------- Collision, Gravity, Movement ----------------------
	
APPLY_GRAVITY:
	beq $s4, FALL_SPEED, FALL_SPEED_REACHED
	addi $s4, $s4, GRAV_ACCEL
	FALL_SPEED_REACHED:
	jr $ra
	
UPDATE_PLAYER_VERT:
	move $t0, $s4
	add $s2, $s2, $t0
	
	# Prevent player from going above the screen
    	blt $s2, 0, CLAMP_TOP
    	jr $ra

	CLAMP_TOP:
    	li $s2, 0
    	li $s4, 1     # force falling
    	jr $ra
	
CHECK_BOUNDS:
	blt $s1, 0, LEFT_BOUND
	
	li $t0, SCREEN_WIDTH
	sub $t0, $t0, PLAYER_WIDTH
	
	bgt $s1, $t0, RIGHT_BOUND
	
	j CHECK_FALL
	blt $s2, 0, TOP_BOUND #
	
	LEFT_BOUND:
	li $s1, 0
	j CHECK_FALL
	
	RIGHT_BOUND:
	move $s1, $t0
	j CHECK_FALL
	
	TOP_BOUND:#
	li $s2, 0
	li $s4, 1
	li $s3, 0
	j CHECK_FALL#
	
	CHECK_FALL:

	j END_CHECK_BOUNDS


	END_CHECK_BOUNDS:
	jr $ra
		
CHECK_PLATFORMS: 
	move $a0, $ra
	blt $s4, 0, END_CHECK_PLATFORMS
	
	la $t0, PLATFORM1
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	lw $a3, 8($t0)
	jal CHECK_PLATFORM_LOGIC
	beq $v0, 1, END_CHECK_PLATFORMS
	
	la $t0, PLATFORM2
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	lw $a3, 8($t0)
	jal CHECK_PLATFORM_LOGIC
	beq $v0, 1, END_CHECK_PLATFORMS
	
	la $t0, PLATFORM2B
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	lw $a3, 8($t0)
	jal CHECK_PLATFORM_LOGIC
	beq $v0, 1, END_CHECK_PLATFORMS
	
	la $t0, PLATFORM3
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	lw $a3, 8($t0)
	jal CHECK_PLATFORM_LOGIC
	beq $v0, 1, END_CHECK_PLATFORMS
	
	la $t0, PLATFORM4
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	lw $a3, 8($t0)
	jal CHECK_PLATFORM_LOGIC
	beq $v0, 1, END_CHECK_PLATFORMS
	
	la $t0, PLATFORM5
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	lw $a3, 8($t0)
	jal CHECK_PLATFORM_LOGIC
	beq $v0, 1, END_CHECK_PLATFORMS
	
	END_CHECK_PLATFORMS:
	move $ra, $a0
	jr $ra
	
CHECK_PLATFORM_LOGIC: 		#(ra, x, y, width)
	# cast down from player
	move $t3, $s1 			# t3 = player x
	addi $t3, $t3, 1 		# center ray
	move $t4, $s2 			# t4 = player y
	addi $t4, $t4, PLAYER_HEIGHT 	# move to feet
	
	# Check same level as platform
	bne $t4, $a2, NO_COLLISION
	
	# Check x bounds
	blt $t3, $a1, NO_COLLISION
	add $t1, $a1, $a3
	bgt $t3, $t1, NO_COLLISION
	
	# Else Collision
	COLLISION:
	li $s4, 0
	li $s3, 1
	
	# Set double jump
	beq $s6, 0, NO_DOUBLE_JUMP
	li $s6, 1
	
	NO_DOUBLE_JUMP:
	li $v0, 1
	jr $ra

	NO_COLLISION:
	li $s3 0
	li $v0, 0
	jr $ra

		
CHECK_OBJECT_COLLISION:
	
	move $a0, $ra
	
	CHECK_PICKUP1:
	
	# Check gravity pickup
	la $t0, PICKUP1 
	lw $t1, 8($t0)
	beq $t1, 1, CHECK_PICKUP2
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	jal CHECK_PICKUP_COLLISION
	
	# If the gravity pickup is collided
	beq, $v0, 0, CHECK_PICKUP2
	li $s5, SLOW_TIME
	la $t0, PICKUP1
	li $t1, 1
	sw $t1, 8($t0)
	
	CHECK_PICKUP2:
	
	# Check double jump pickup
	la $t0, PICKUP2
	lw $t1, 8($t0)
	beq $t1, 1, CHECK_PICKUP_HEALTH
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	jal CHECK_PICKUP_COLLISION
	
	# If the double jump pickup is collided
	beq, $v0, 0, CHECK_PICKUP_HEALTH
	li $s6, 1
	la $t0, PICKUP2
	li $t1, 1
	sw $t1, 8($t0)
	

	
	CHECK_PICKUP_HEALTH:
	# Check health pickup
	la $t0, PICKUP_HEALTH
	lw $t1, 8($t0)
	beq $t1, 1, END_CHECK_OBJECTS
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	jal CHECK_PICKUP_COLLISION
	
	# If the Health is collided 
	beq, $v0, 0, END_CHECK_OBJECTS
	la $t2, HEALTH		
    	lw $t3, 0($t2)				# $ t3 = HEALTH
    	li $t4, 3
    	bge $t3, $t4, SKIP_INC_HEALTH   	# if HEALTH >= 3, skip


	# Increase Health
    	addi $t3, $t3, 1
    	sw $t3, 0($t2)
    	la $t0, PICKUP_HEALTH
	li $t1, 1
	sw $t1, 8($t0)

	SKIP_INC_HEALTH:
	la $t0, PICKUP_HEALTH
	li $t1, 1
	sw $t1, 8($t0)
	
	END_CHECK_OBJECTS:
	move $ra, $a0
	jr $ra
	
CHECK_PICKUP_COLLISION: 

	move $t0, $a1
	addi $t0, $t0, 2 	# right side x of pickup
	addi $a1, $a1, -1 	# left side x of pickup
	
	move $t1, $a2
	addi $t1, $t1, 2 	# bottom side y of  pickup
	addi $a2, $a2, -1 	# top side y of pickup
	
	move $t3, $s1 		# t3 = player x
	addi $t3, $t3, 1 	# center player x
	move $t4, $s2 		# t4 = player y
	addi $t4, $t4, 2 	# move to middle y
	
	blt $t3, $a1, NO_PICKUP_COLLISION
	bgt $t3, $t0, NO_PICKUP_COLLISION
	blt $t4, $a2, NO_PICKUP_COLLISION
	bgt $t4, $t1, NO_PICKUP_COLLISION
	
	PICKUP_COLLISION:
	li $v0, 1
	jr $ra
	
	NO_PICKUP_COLLISION:
	li $v0, 0
	jr $ra
		
# ----------------------- End of Collision, Gravity, Movement ----------------------

# ----------------------- Moving Platforms, Objects ----------------------

MOVE_OBJECTS:
	
	move $a0, $ra
	
	la $a1, PLATFORM3
	jal MOVE_LOGIC
	
	la $a1, PICKUP2
	jal MOVE_LOGIC
	
	move $ra, $a0
	jr $ra
	
MOVE_LOGIC: #(prevRA, address)

	lw $t0, 0($a1) #x
	lw $t1, 12($a1) #min
	lw $t2, 16($a1) #max
	lw $t3, 20($a1) #dir
	
	ble $t0, $t1, MOVE_BOUND
	bge $t0, $t2, MOVE_BOUND
	j MOVE_IN_DIR
	
	MOVE_BOUND:
	li $t4, -1
	mult $t3, $t4
	mflo $t3
	sw $t3, 20($a1)
	
	MOVE_IN_DIR:
	add $t0, $t0, $t3
	sw $t0, 0($a1)
	
	jr $ra

# ----------------------- End of Moving Platforms, Objects ----------------------
	
# ----------------------- Drawing ----------------------

CLEAR_SCREEN: # Clear the screen to prepare for draw
	li $t0, BASE_ADDRESS
	li $t1, SCREEN_WIDTH
	li $t2, BACKGROUND_COLOUR
	li $t3, 4
	mult $t1, $t1
	mflo $t1
	mult $t1, $t3
	mflo $t1
	add $t1, $t0, $t1
	
	CLEAR_SCREEN_LOOP:
		bgt $t0, $t1, END_CLEAR_SCREEN
		sw $t2, 0($t0)
		addi $t0, $t0, 4
		j CLEAR_SCREEN_LOOP
	END_CLEAR_SCREEN:
		jr $ra
		
DRAW_PLATFORMS:

	# Store ra in $a0
	move $a0, $ra 
	
	# Platform 1
	la $t0, PLATFORM1
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	lw $a3, 8($t0)
	jal DRAW_PLATFORM
	
	la $t0, PLATFORM2
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	lw $a3, 8($t0)
	jal DRAW_PLATFORM
	
	la $t0, PLATFORM2B
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	lw $a3, 8($t0)
	jal DRAW_PLATFORM
	
	la $t0, PLATFORM3
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	lw $a3, 8($t0)
	jal DRAW_PLATFORM
	
	la $t0, PLATFORM4
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	lw $a3, 8($t0)
	jal DRAW_PLATFORM
	
	la $t0, PLATFORM5
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	lw $a3, 8($t0)
	jal DRAW_PLATFORM
	
	# Restore address and return to the caller
	move $ra, $a0
	jr $ra
	
DRAW_PLATFORM: #(origRA, x, y, width) -- to avoid using the stack, store the caller's caller ra in a0
	
	# t0 = (x,y)
	li $t0, SCREEN_WIDTH
	li $t2, 4
	
	mult $t0, $a2	# t0 = SCREEN_WIDTH*y
	mflo $t0
	add $t0, $t0, $a1 # t0 = SCREEN_WIDTH*y + x
	
	mult $t0, $t2 # byte offset
	mflo $t0
	addi $t0, $t0, BASE_ADDRESS
	
	# t3 end address
	move $t3, $a3
	mult $t2, $t3
	mflo $t3
	add $t3, $t0, $t3

	# t4 load platform colour
	li $t4, DARK_GREEN
	
	DRAW_PLATFORM_LOOP:
		bgt $t0, $t3, END_DRAW_PLATFORM_LOOP
		sw $t4, 0($t0)
		addi $t0, $t0, 4
		
		j DRAW_PLATFORM_LOOP
	
	END_DRAW_PLATFORM_LOOP:
		jr $ra
		
		
DRAW_PLAYER: # Draw player character at the current PLAYER_POS
	
	# t1=x, t2=y, t3=color, t6 secondary color
	move $t1, $s1
	move $t2, $s2
	li $t3, LIME_GREEN
	li $t7, PINK
	
	# Change color if double jump is active
	beq $s6, 1, DRAW_FROG_DOUBLE_JUMP
	j DRAW_FROG
	DRAW_FROG_DOUBLE_JUMP:
	li $t3, PURPLE       # entire frog becomes dark blue
	j DRAW_FROG
	
	
	DRAW_FROG:
	
	# t4=framebuffer, t5=(x,y)
	li $t4, BASE_ADDRESS
	li $t5, SCREEN_WIDTH
	li $t6, 4
	mult $t5, $t2 		# y*width
	mflo $t5			
	add $t5, $t5, $t1		# y*width + x
	mult $t5, $t6		# (y*width + x)*4
	mflo $t5
	
	add $t5, $t5, $t4	# Offset by base address
	
	li $t6, BLACK
	
	sw $t6, 0($t5)		# player row 1
	#sw $t3, 4($t5)
	sw $t6, 8($t5)
	

	addi $t5, $t5, 256	# player row 2
	sw $t3, 0($t5)
	sw $t3, 4($t5)
	sw $t3, 8($t5)
	
	addi $t5, $t5, 256	# player row 3
	sw $t3, 0($t5)
	sw $t7, 4($t5)
	sw $t3, 8($t5)
	
	addi $t5, $t5, 256	# player row 4
	sw $t3, 0($t5)
	#sw $t3, 4($t5)
	sw $t3, 8($t5)
	
	jr $ra			
	
	
DRAW_PICKUPS:
	move $a0, $ra

	DRAW_PICKUP1:
	la $t0, PICKUP1
	lw $t1, 8($t0)
	beq $t1, 1, DRAW_PICKUP2
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	li $a3, RED
	jal DRAW_PICKUP
	
	DRAW_PICKUP2:
	la $t0, PICKUP2
	lw $t1, 8($t0)
	beq $t1, 1, DRAW_PICKUP_HEALTH
	lw $a1, 0($t0)
	lw $a2, 4($t0)
	li $a3, DARK_PURPLE
	jal DRAW_PICKUP
	

	
	DRAW_PICKUP_HEALTH:
    	la $t0, PICKUP_HEALTH
    	lw $t1, 8($t0)
    	beq $t1, 1, END_DRAW_PICKUPS

    	lw $a1, 0($t0)
    	lw $a2, 4($t0)
    	li $a3, PINK      
    	jal DRAW_PICKUP
	
	END_DRAW_PICKUPS:
	move $ra, $a0
	jr $ra
	
DRAW_PICKUP: #(prevRA, x, y, color)
	# Get t0 to (x,y)
	li $t0, SCREEN_WIDTH
	li $t2, 4
	
	mult $t0, $a2 
	mflo $t0
	add $t0, $t0, $a1	# t0 = y*SCREEN_WIDTH + x
	mult $t0, $t2
	mflo $t0
	addi $t0, $t0, BASE_ADDRESS

	sw $a3 4($t0) 		#mushroom row 1
	
	
	addi $t0, $t0, 256	# mushroom row 2
	sw $a3, 0($t0)
	sw $a3, 4($t0)
	sw $a3, 8($t0)
	
	li $a3, WHITE
	addi $t0, $t0, 256	# mushroom row 3
	sw $a3, 4($t0)
	
	jr $ra

DRAW_SCREEN: #(address(screen))
	li $t0, BASE_ADDRESS
	li $t1, SCREEN_WIDTH
	li $t3, 4
	mult $t1, $t1
	mflo $t1
	mult $t1, $t3
	mflo $t1
	add $t1, $t0, $t1

	DRAW_SCREEN_LOOP:
		bge $t0, $t1, END_DRAW_SCREEN_LOOP
		lw $t2, 0($a0)
		sw $t2, 0($t0)
		addi $t0, $t0, 4
		addi $a0, $a0, 4
		j DRAW_SCREEN_LOOP
	END_DRAW_SCREEN_LOOP:
		jr $ra


# ****************** DRAW HEALTH HEARTS ***********************

DRAW_HEARTS:
    move $t9, $ra

    la $t0, HEALTH
    lw $t1, 0($t0)     # $t1 = HEALTH
    
    li $t2, 0
    beq $t1, $t2, DRAW_ZERO_HEARTS
	
    li $t2, 1
    beq $t1, $t2, DRAW_ONE_HEART

    li $t2, 2
    beq $t1, $t2, DRAW_TWO_HEARTS

    li $t2, 3
    beq $t1, $t2, DRAW_THREE_HEARTS
    

    j END_DRAW_HEARTS  # fallback if health not 0-3
    
    
    
# -----------------------------
	DRAW_ZERO_HEARTS:
    	li $a0, 2          # x
    	li $a1, 2          # y
    	li $a3, DARK_BLUE
    	jal DRAW_HEART_LOGIC
    
    	li $a0, 8          # x
    	li $a1, 2          # y
    	li $a3, DARK_BLUE
    	jal DRAW_HEART_LOGIC
    
    	li $a0, 14          # x
    	li $a1, 2          # y
    	li $a3, DARK_BLUE
    	jal DRAW_HEART_LOGIC
    
    	j END_DRAW_HEARTS

# -----------------------------
	DRAW_ONE_HEART:
    	li $a0, 2          # x
    	li $a1, 2          # y
    	li $a3, PINK
    	jal DRAW_HEART_LOGIC
    
    	li $a0, 8          # x
    	li $a1, 2          # y
    	li $a3, DARK_BLUE
    	jal DRAW_HEART_LOGIC
    
    	li $a0, 14          # x
    	li $a1, 2          # y
    	li $a3, DARK_BLUE
    	jal DRAW_HEART_LOGIC
    
    	j END_DRAW_HEARTS

# -----------------------------
	DRAW_TWO_HEARTS:

    	li $a0, 2          # x
    	li $a1, 2          # y
    	li $a3, PINK
    	jal DRAW_HEART_LOGIC
    
    	li $a0, 8          # x
    	li $a1, 2          # y
    	li $a3, PINK
    	jal DRAW_HEART_LOGIC
    
    	li $a0, 14          # x
    	li $a1, 2          # y
    	li $a3, DARK_BLUE
    	jal DRAW_HEART_LOGIC
    
    	j END_DRAW_HEARTS

# -----------------------------
	DRAW_THREE_HEARTS:

    	li $a0, 2          # x
    	li $a1, 2          # y
    	li $a3, PINK
    	jal DRAW_HEART_LOGIC
    
    	li $a0, 8          # x
    	li $a1, 2          # y
    	li $a3, PINK
    	jal DRAW_HEART_LOGIC
    
    	li $a0, 14          # x
    	li $a1, 2          # y
    	li $a3, PINK
    	jal DRAW_HEART_LOGIC
    
    	j END_DRAW_HEARTS

# -----------------------------
	END_DRAW_HEARTS:
    	move $ra, $t9
    	jr $ra

# ------------------------ DRAWING HEART LOGIC ----------------------------------------
    
DRAW_HEART_LOGIC:
    li $t0, SCREEN_WIDTH
    mul $t1, $a1, $t0         # row offset = y * SCREEN_WIDTH
    add $t1, $t1, $a0         # add x offset
    li $t2, 4
    mul $t1, $t1, $t2         # convert units to byte offset
    li $t3, BASE_ADDRESS
    add $t1, $t1, $t3         # final framebuffer address
    
    
    # heart row 1
    sw $a3 4($t1)
    sw $a3 12($t1)

    
    # heart row 2
    addi $t1, $t1, 256
    sw $a3 ($t1)
    sw $a3 4($t1)
    sw $a3 8($t1)
    sw $a3 12($t1)
    sw $a3 16($t1)
    
    # heart row 3
    addi $t1, $t1, 256
    sw $a3 4($t1)
    sw $a3 8($t1)
    sw $a3 12($t1)

    # heart row 4
    addi $t1, $t1, 256
    sw $a3 8($t1)
 
    jr $ra

# ------------------------ DRAWING SINGLE HEART  ----------------------------------------

# ************************ RESTART ************************************************

RESTART: # Set all variables back to their original values

	move $t9, $ra     # Save return address
	
	RESET_MOVING_PLATFORMS: # Reset platform position for moving platforms
	la $t0, PLATFORM3
	li $t1, PLATFORM3_START_X
	sw $t1, 0($t0)
	li $t1, 1
	sw $t1, 20($t0)
	
	RESET_PICKUPS: 
	# Set pickup status back to false of all pickups
	
	# reset slow gravity pickup
	la $t0, PICKUP1
	li $t1, 0
	sw $t1, 8($t0)
	
	# reset double jump pickup
	la $t0, PICKUP2
	li $t1, PICKUP2_X
	sw $t1, 0($t0)
	li $t1, 0
	sw $t1, 8($t0)
	li $t1, -1
	sw $t1, 20($t0)
	
	# Reset health pickup collected flag
	la $t0, PICKUP_HEALTH
	li $t1, 0
	sw $t1, 8($t0)
	
	RESET_PLAYER: # Reset player variables
	li $s1, PLAYER_START_X
	li $s2, PLAYER_START_Y
	li $s3, 0
	li $s4, 0
	li $s5, 0
	li $s6, 0
	li $s7, 0

	
	RESET_GAME_STATE:
	li $s0, 0
	
	RESET_HEALTH:
	la $t0, HEALTH
	li $t1, 3
	sw $t1, 0($t0)
	
	jal CLEAR_SCREEN  # This will overwrite $ra

	move $ra, $t9     # Restore return address
	jr $ra            # Return properly



# ************************ RESTART ************************************************


#********************** WIN / FAIL CHECKS ***************************************
	
CHECK_GAME_STATUS:
	
	# Load Platform 4 info
    	la $t0, PLATFORM5
    	lw $t1, 0($t0)       # platform5_x
	lw $t2, 4($t0)       # platform5_y
    	lw $t3, 8($t0)       # platform5_width

    	# Check if player's feet (bottom center) are aligned with Platform 4 Y
    	move $t4, $s2        			# player_y
    	addi $t4, $t4, PLAYER_HEIGHT  		# player's feet Y

    	bne $t4, $t2, CHECK_FAIL_GAME   	# not aligned with platform Y

    	# Check if player x is within the platform 4's range
    	move $t5, $s1        			# player x
    	addi $t5, $t5, 1      			# center x of player

    	blt $t5, $t1, CHECK_FAIL_GAME 		# before platform start
    	add $t6, $t1, $t3             		# platform5_x + width
    	bgt $t5, $t6, CHECK_FAIL_GAME 		# after platform end

    	# If both conditions pass, we win!
    	li $s0, 1
    	j DONE
	
	CHECK_FAIL_GAME:
	bgt $s2, SCREEN_HEIGHT, DECREASE_HEALTH
	j DONE
	
	DECREASE_HEALTH:
    	# Decrease health by 1
    	la $t0, HEALTH
    	lw $t1, 0($t0)		# load current health
    	blez $t1, FAIL		# if health is less than or equal to 0, fail
    	addi $t1, $t1, -1	# subtract 1
    	sw $t1, 0($t0)		# store updated health

    	# Reset player position
    	li $s1, PLAYER_START_X
    	li $s2, PLAYER_START_Y
    	li $s4, 0
    	li $s3, 0

    	# Check if health is 0
    	beqz $t1, FAIL

    j DONE
		
	WIN:
	li $s0, 1
	j DONE
	
	FAIL:
	li $s0, 2
	j DONE
			
